using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var noteTools = host.Services.GetRequiredService<NoteTools>();

var tools = new AIToolCollection
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(noteTools.SaveNote),
    AIFunctionFactory.Create(noteTools.GetNotes),
};

var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information (perform multiple searches with different queries)
    2. Saving key findings as notes
    3. After gathering enough information, retrieve all notes and produce a comprehensive summary

    Always save important findings before summarizing. Use varied search queries to get diverse perspectives.
    """)
{
    Tools = tools,
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// --- Tool implementations ---

public sealed class ResearchTools
{
    [Description("Searches the web for information on a query and returns relevant results.")]
    public Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing Search, Google Custom Search, etc.)
        var results = $"""
            Search results for: "{query}"

            1. [Article] Overview and key concepts related to "{query}" - 
               This comprehensive article covers the main points, history, and current state of the topic.
               Key takeaways: The field has seen significant growth, with multiple perspectives emerging.

            2. [Research Paper] Recent advances in "{query}" -
               Published 2025. Discusses latest developments, methodologies, and future directions.
               Conclusion: Continued progress expected with broader applications.

            3. [News] Latest developments in "{query}" -
               Recent coverage highlights new breakthroughs, industry adoption, and expert opinions.
               Notable quote: "This represents a paradigm shift in how we approach the problem."
            """;

        return Task.FromResult(results);
    }
}

public sealed class NoteTools
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note with key findings. Use this to record important information discovered during research.")]
    public Task<string> SaveNote(
        [Description("The note content to save")] string content)
    {
        _notes.Add(content);
        return Task.FromResult($"Note saved (total notes: {_notes.Count}).");
    }

    [Description("Retrieves all saved research notes to compile into a summary.")]
    public Task<string> GetNotes()
    {
        if (_notes.Count == 0)
            return Task.FromResult("No notes saved yet.");

        var result = string.Join("\n\n---\n\n",
            _notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
        return Task.FromResult(result);
    }
}

