arguments.new_str:
using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var openAIClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAIClient.GetResponsesClient().AsIChatClient();

var noteTools = new NoteTools();

var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(noteTools.SaveNote),
    AIFunctionFactory.Create(noteTools.GetNotes),
};

var agent = new ChatClientAgent(chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (perform multiple searches with different queries)
        2. Saving key findings as notes
        3. After gathering enough information, retrieve all notes and produce a comprehensive summary

        Always save important findings before summarizing. Use varied search queries to get diverse perspectives.
        """,
    name: "ResearchAgent",
    tools: tools);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var response = await agent.RunAsync(messages, session: null, options: null);

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n--- Research complete ---");

